lemma comp {R : ProbabilisticTheory} {τ : G →* Reversible R R}
    {Φ : Channel P Q} {Ψ : Channel Q R} (hΦ : IsIntertwining ρ σ Φ)
    (hΨ : IsIntertwining σ τ Ψ) : IsIntertwining ρ τ (Ψ.comp Φ)

lemma exists_incl_eq_of_toQuasilocal_eq {i j : R} {a : A i} {b : A j}
    (h : toQuasilocal N i a = toQuasilocal N j b) :
    ∃ (k : R) (hik : i ≤ k) (hjk : j ≤ k), N.incl hik a = N.incl hjk b

lemma sumIn_count_tsum [Countable ι] {Λ : R}
    (h : Integrable (Φ.termIn Λ) Measure.count) :
    Φ.sumIn Measure.count Λ = ∑' i, Φ.termIn Λ i
